patches.find:
.title-gear { width: .42rem; height: .42rem; display: grid; place-items: center; background: rgba(12,15,14,.55); border: 1px solid #2c3a35; border-radius: .06rem; color: var(--text-hi, #d8e3de); cursor: pointer; }
.title-gear:hover { border-color: var(--mint-700, #4ed8af); color: var(--mint-700, #4ed8af); }
.title-gear .icon { width: .22rem; height: .22rem; }

patches.replace:
.set-seg { grid-column: 2 / 4; justify-self: start; display: flex; flex-wrap: wrap; border: 1px solid var(--line-2); }
.set-input { grid-column: 2 / 3; background: #0c0f0e; border: 1px solid var(--line-2); color: var(--text-hi, #d8e3de); padding: .08rem .12rem; font-size: .14rem; border-radius: .04rem; min-width: 3.2rem; }
.set-apply { grid-column: 3 / 4; justify-self: start; border: 1px solid var(--mint-700, #4ed8af); background: transparent; color: var(--mint-700, #4ed8af); padding: .08rem .18rem; font-size: .13rem; border-radius: .04rem; cursor: pointer; }
.set-apply:disabled { opacity: .4; }
.set-hint--tight { margin-top: .04rem; }
